import{_ as l,b as t,c as n,g as o}from"./chunks/framework.86O3EbG5.js";const x=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"课文三则","author":"oasis","date":"2026-10-20T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/classical-chinese/1.md","filePath":"articles/books/classical-chinese/1.md"}'),s={name:"articles/books/classical-chinese/1.md"};function r(g,i,d,h,e,a){return t(),n("div",null,[...i[0]||(i[0]=[o('<h2 id="《鲁施氏有二子》" tabindex="-1">《鲁施氏有二子》</h2><p>鲁施氏有二子，其一好学，其一好兵。好学者以术干齐侯；齐侯纳之，以为诸公子之傅。好兵者之楚，以法干楚王；王悦之，以为军正。禄富其家，爵荣其亲。</p><p>施氏之邻人孟氏，同有二子，所业亦同，而窘于贫。羡施氏之有，因从请进趋之方。二子以实告孟氏。孟氏之一子之秦，以术干秦王。秦王曰：“当今诸侯力争，所务兵食而已。若用仁义治吾国，是灭亡之道。”遂宫而放之。</p><p>其一子之卫，以法干卫侯。卫侯曰：“吾弱国也，而摄乎大国之间。大国吾事之，小国吾抚之，是求安之道。若赖兵权，灭亡可待矣。若全而归之，适于他国。为吾之患不轻矣。”遂刖之，而还诸鲁。</p><p>既反，孟氏之父子叩胸而让施氏。施氏曰：“凡得时者昌，失时者亡。子道与吾同，而功与吾异，失时者也，非行之谬也。且天下理无常是，事无常非。先日所用，今或弃之；今之所弃，后或用之。此用与不用，无定是非也。投隙抵时，应事无方，属乎智。智苟不足，使若博如孔丘，术如吕尚，焉往而不穷哉？”孟氏父子舍然无愠容，曰：“吾知之矣，子勿重言！”</p><h3 id="重点词汇" tabindex="-1">重点词汇</h3><ul><li><strong>干（gān）</strong>：干谒，求仕</li><li><strong>之</strong>：动词，往、到；代词；结构助词</li><li><strong>让</strong>：责备（≠谦让）</li><li><strong>诸</strong>：兼词，之于</li><li><strong>反</strong>：通“返”，返回</li><li><strong>摄</strong>：夹</li><li><strong>窘</strong>：困迫</li><li><strong>务</strong>：致力</li><li><strong>穷</strong>：困厄，走投无路（不是贫穷）</li><li><strong>或</strong>：或许</li></ul><h3 id="重点语法" tabindex="-1">重点语法</h3><ol><li><strong>使动用法</strong><ul><li>禄富其家、爵荣其亲：富、荣，形使动</li><li>全而归之：全，形使动</li></ul></li><li><strong>判断句</strong>：吾弱国也；失时者也，非行之谬也。（“也”字判断，“非”表否定判断）</li><li><strong>被动句</strong>：窘于贫（于引介被动）</li><li><strong>宾语前置</strong><ul><li>大国吾事之（强调宾语前置）</li><li>焉往而不穷（疑问代词宾语前置）</li></ul></li><li><strong>所字结构、者字结构</strong>：所业、所务；好学者、得时者</li><li><strong>兼词</strong>：诸 = 之于；乎 = 于</li><li><strong>通假字</strong>：反 = 返；舍 = 释</li></ol><h2 id="《九方皋相马》" tabindex="-1">《九方皋相马》</h2><p>秦穆公谓伯乐曰：“子之年长矣，子姓有可以求马者乎？”伯乐对曰：“良马可形容筋骨相也。天下之马者，若灭若没，若亡若失，若此者绝尘弭辙，臣之子皆下才也，可告以良马，不可告以天下之马也。臣有所与共担纆薪菜者，有九方皋，此其于马非臣之下也。请见之。”</p><p>穆公见之，使行求马，三月而反报曰：“已得之矣，在沙丘。”穆公曰：“何马也？”对曰：“牝而黄。”使人往取之，牡而骊。</p><p>穆公不说，召伯乐而谓之曰：“败矣，子所使求马者！色物牝牡尚弗能知，又何马之能知也？”伯乐喟然太息曰：“一至于此乎！是乃其所以千万臣而无数者也。若皋之所观，天机也，得其精而忘其粗，在其内而忘其外；见其所见，不见其所不见，视其所视，而遗其所不视。若皋之相者，乃有贵乎马者也。”</p><p>马至，果天下之马也。</p><h3 id="重点词汇-1" tabindex="-1">重点词汇</h3><ul><li><strong>子姓</strong>：子孙后辈（≠姓氏）</li><li><strong>形容</strong>：形体外貌（古今异义）</li><li><strong>相（xiàng）</strong>：鉴别，观察</li><li><strong>纆</strong>：绳索；薪菜：采薪，菜通采</li><li><strong>见（xiàn）</strong>：使……谒见，使动</li><li><strong>反</strong>：通“返”；说：通“悦”</li><li><strong>牝</strong>：母；牡：公；骊：纯黑</li><li><strong>太息</strong>：长叹</li><li><strong>所以</strong>：……的缘故 / ……的地方</li><li><strong>遗</strong>：舍弃</li></ul><h3 id="重点语法-1" tabindex="-1">重点语法</h3><ol><li><strong>介宾短语后置</strong><ul><li>可告以良马 → 可〔以良马〕告之</li><li>贵乎马 → 贵于马</li></ul></li><li><strong>宾语前置</strong>：何马之能知，“之”作提宾标志</li><li><strong>谓语前置（感叹倒装）</strong>：败矣，子所使求马者！</li><li><strong>判断句（也 / 乃）</strong>：臣之子皆下才也；若皋之所观，天机也；果天下之马也；是乃其所以千万臣而无数者也。</li><li><strong>所字结构、者字结构</strong>：所与共担纆薪菜者、所使求马者、所见、所不见</li><li><strong>通假字</strong>：反 = 返；说 = 悦；菜 = 采</li><li><strong>使动用法</strong>：请见之，使之见（使九方皋谒见穆公）</li></ol><p>所字结构的定义和例句见 <a href="/articles/books/classical-chinese/1-1.html">所字结构</a>。</p><h2 id="《景公射出质》" tabindex="-1">《景公射出质》</h2><p>晏子没十有七年，景公饮诸大夫酒。公射出质，堂上唱善，若出一口。公作色太息，播弓矢。</p><p>弦章入，公曰：“章！自吾失晏子，于今十有七年，未尝闻吾过不善。今射出质，而唱善者若出一口。”弦章对曰：“此诸臣之不肖也：知不足以知君之不善，勇不足以犯君之颜色。然而有一焉，臣闻之：君好之，则臣服之；君嗜之，则臣食之。夫尺蠖食黄则其身黄，食苍则其身苍。君其犹有食谄人之言乎！”</p><p>公曰：“善！今日之言，章为君，我为臣。”</p><p>是时，海人入鱼，公以五十乘赐弦章。章归，鱼乘塞涂。抚其御之手曰：“曩之唱善者，皆欲若鱼者也。昔者，晏子辞赏以正君，故过失不掩。今诸臣谄谀以干利，故出质而唱善如出一口。今所辅于君未见于众，而受若鱼，是反晏子之义而顺谄谀之欲也。”固辞鱼不受。</p><p>君子曰：“弦章之廉，乃晏子之遗行也。”</p><h3 id="重点词汇-2" tabindex="-1">重点词汇</h3><ul><li><strong>没（殁）</strong>：死亡；有（又），整数零数之间</li><li><strong>饮（yìn）</strong>：使动，使……饮酒</li><li><strong>太息</strong>：长叹</li><li><strong>知（智）</strong>：通假，智慧</li><li><strong>颜色</strong>：脸色、威严（古今异义）</li><li><strong>干（gān）</strong>：求取（干利）</li><li><strong>曩</strong>：先前</li><li><strong>涂（途）</strong>：道路</li><li><strong>御</strong>：车夫</li><li><strong>固</strong>：坚决</li></ul><h3 id="重点语法-2" tabindex="-1">重点语法</h3><h4 id="通假字" tabindex="-1">通假字</h4><ul><li>没 = 殁；十有七年，有 = 又；知 = 智；涂 = 途</li></ul><h4 id="词类活用" tabindex="-1">词类活用</h4><ol><li>饮诸大夫酒：动词<strong>使动</strong>，使……饮</li><li>晏子辞赏以正君：形容词<strong>使动</strong>，正君 = 使君正，匡正君主</li></ol><h4 id="者字结构-v-者" tabindex="-1">者字结构（V + 者）</h4><ul><li>唱善者：叫好的人；欲若鱼者：想要这些鱼的人</li></ul><h4 id="所字结构" tabindex="-1">所字结构</h4><ul><li>所辅：所辅佐（的成效）</li></ul><h4 id="判断句" tabindex="-1">判断句</h4><ol><li>此诸臣之不肖也（……，……也）</li><li>曩之唱善者，皆欲若鱼者也（……者，……也）</li><li>是反晏子之义而顺谄谀之欲也</li><li>弦章之廉，乃晏子之遗行也（乃……也）</li></ol><h4 id="被动句" tabindex="-1">被动句</h4><ol><li>过失不掩：意念被动，过失不被掩盖</li><li>未见于众：<strong>见 + 于</strong>被动句式（王力四大被动之一，被众人看见）</li></ol><h4 id="之-取消句子独立性" tabindex="-1">“之”取消句子独立性</h4><ul><li>君之不善；弦章之廉</li></ul><h4 id="兼词" tabindex="-1">兼词</h4><ul><li>焉：有一焉，于此，在这里</li></ul><h4 id="双宾语" tabindex="-1">双宾语</h4><ul><li>公以五十乘赐弦章：赐（间接宾语：弦章）（直接宾语：五十乘鱼）</li></ul><h4 id="连动句" tabindex="-1">连动句</h4><ul><li>公作色太息，播弓矢（同一主语，连续动作）</li></ul><h4 id="省略句" tabindex="-1">省略句</h4><p>多处省略主语、宾语（之）。</p><h3 id="古代文化常识" tabindex="-1">古代文化常识</h3><ol><li><strong>职官等级</strong>：诸侯下面分卿、大夫、士；大夫为国君高级臣僚。</li><li><strong>礼制：燕礼、燕射</strong>。国君闲暇宴群臣，席间燕射，射礼重在观德，不只是竞技。</li><li><strong>车马</strong>：一乘 = 一车四马；御 = 车夫。</li><li><strong>贡赐制度</strong>：地方献特产叫入 / 贡；上给予下叫赐。</li><li><strong>先秦谏议与讽谏</strong>：臣子委婉比喻规劝君主；君主纳谏为美德。</li><li><strong>思想观念</strong>：上行下效；义利之辨，无功不接受赏赐，士大夫清廉操守。</li><li><strong>文体习惯</strong>：“君子曰”是先秦评议人物的固定写法。</li><li><strong>六艺</strong>：贵族必修礼、乐、射、御、书、数。</li></ol><h2 id="《原宪居鲁》" tabindex="-1">《原宪居鲁》</h2><p>原宪居鲁，环堵之室，茨以生草，蓬户不完，桑以为枢而瓮牖，二室，褐以为塞，上漏下湿，匡坐而弦。</p><p>子贡乘大马，中绀而表素，轩车不容巷，往见原宪。原宪华冠縰履，杖藜而应门。</p><p>子贡曰：“嘻！先生何病？”原宪应之曰：“宪闻之：‘无财谓之贫，学而不能行谓之病。’今宪，贫也，非病也。”子贡逡巡而有愧色。</p><p>原宪笑曰：“夫希世而行，比周而友，学以为人，教以为己，仁义之慝，舆马之饰，宪不忍为也。”</p><h3 id="重点词汇-3" tabindex="-1">重点词汇</h3><ul><li><strong>环堵</strong>：四面围墙，一丈见方的小屋。环，环绕；堵，土墙，一丈为一堵</li><li><strong>茨（cí）</strong>：用草盖屋顶</li><li><strong>蓬户</strong>：蓬草编的门</li><li><strong>枢（shū）</strong>：门轴</li><li><strong>瓮牖（wèng yǒu）</strong>：用破瓮做的窗户</li><li><strong>褐（hè）</strong>：粗麻布，粗布衣服</li><li><strong>匡坐</strong>：正坐，端坐</li><li><strong>弦</strong>：弹琴，鼓琴</li><li><strong>绀（gàn）</strong>：红青色，深青带红的颜色</li><li><strong>轩车</strong>：有帷幕、较高的贵族大车</li><li><strong>华冠</strong>：破旧的帽子；华，通“花”，破烂</li><li><strong>縰（xǐ）履</strong>：无后跟的鞋，草鞋</li><li><strong>杖藜</strong>：拄着藜木拐杖；杖，名词作动词，拄</li><li><strong>逡巡（qūn xún）</strong>：退却，局促不安的样子</li><li><strong>希世</strong>：迎合世俗。希，通“晞”，求，迎合</li><li><strong>比周</strong>：结党营私，互相勾结</li><li><strong>慝（tè）</strong>：邪恶，奸邪</li><li><strong>舆马</strong>：车马</li></ul><h3 id="重点语法-3" tabindex="-1">重点语法</h3><h4 id="通假字-1" tabindex="-1">通假字</h4><ul><li>华 = 花，破旧；希 = 晞，迎合、求取</li></ul><h4 id="词类活用-1" tabindex="-1">词类活用</h4><ol><li><strong>桑以为枢</strong>：名词作动词，桑（木），用桑木做</li><li><strong>杖藜而应门</strong>：名词作动词，杖，拄着</li><li><strong>匡坐而弦</strong>：名词作动词，弦，弹琴、鼓琴</li></ol><h4 id="者字结构" tabindex="-1">者字结构</h4><p>本篇无典型者字结构。</p><h4 id="所字结构-1" tabindex="-1">所字结构</h4><p>本篇无典型所字结构。</p><h4 id="判断句-1" tabindex="-1">判断句</h4><ol><li>无财谓之贫，学而不能行谓之病（谓字判断句）</li><li>今宪，贫也，非病也（……，……也；否定判断“非”）</li></ol><h4 id="被动句-1" tabindex="-1">被动句</h4><p>本篇无王力四类典型被动，无意念被动。</p><h4 id="之-取消句子独立性-1" tabindex="-1">“之”取消句子独立性</h4><p>本篇无“之”取独。</p><h4 id="兼词-1" tabindex="-1">兼词</h4><p>本篇无兼词。</p><h4 id="双宾语-1" tabindex="-1">双宾语</h4><p>本篇无双宾语。</p><h4 id="连动句-1" tabindex="-1">连动句</h4><ol><li>杖藜而应门：同一主语，拄藜杖、开门，连续动作</li><li>子贡逡巡而有愧色：子贡退后，面露惭愧之色，连动</li></ol><h4 id="省略句-1" tabindex="-1">省略句</h4><ol><li>茨以生草：省略宾语，茨（室）以生草，用野草盖屋顶</li><li>桑以为枢：桑以（之）为枢，用桑木做门轴</li><li>褐以为塞：褐以（之）为塞，用粗麻布当作堵塞缝隙之物</li></ol><h4 id="介宾短语后置-状语后置" tabindex="-1">介宾短语后置（状语后置）</h4><ol><li><strong>茨以生草</strong> → 以生草茨，用野草覆盖屋顶</li><li><strong>桑以为枢</strong> → 以桑为枢</li></ol><h3 id="古代文化常识-1" tabindex="-1">古代文化常识</h3><ol><li><strong>原宪、子贡</strong>：孔门弟子。原宪（子思），安贫乐道；子贡（端木赐），善于经商，富有，擅长外交。出自《庄子》，体现儒家、道家共同推崇的君子人格。</li><li><strong>居室名物</strong>：环堵、蓬户、瓮牖。上古平民简陋居所；贵族居住高堂大屋，贫富居所差异巨大。</li><li><strong>服饰礼制</strong>：古人上衣下裳；绀、素是古代服色。贵族乘车穿华美的衣服，粗褐是底层百姓、隐士的粗麻布衣服。</li><li><strong>车马制度</strong>：轩车，高级贵族所乘的有篷高车（王力车马篇），和普通马车区分，是身份象征。</li><li><strong>士的操守</strong>：先秦“贫”和“病”的区分。<strong>贫</strong>是缺少财物；<strong>病</strong>是学问道德不能践行。安贫乐道，是孔门君子核心修养。</li><li><strong>比周</strong>：先秦政治术语，结党勾结。《论语》“君子周而不比，小人比而不周”。</li><li><strong>希世（媚俗）</strong>：先秦士人两种人生选择：一是迎合世俗、追名逐利；一是守道安贫，不慕荣华。</li><li><strong>弦</strong>：古代士人的修养，弹琴（乐）属于贵族六艺“乐”。</li></ol>',86)])])}const b=l(s,[["render",r]]);export{x as __pageData,b as default};
